import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const $ = (id) => document.getElementById(id);
const canvas = $('game');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#101414');
scene.fog = new THREE.FogExp2('#111614', 0.027);
const camera = new THREE.PerspectiveCamera(42, innerWidth / innerHeight, .1, 120);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;

const clock = new THREE.Clock();
const hemi = new THREE.HemisphereLight(0xb9c7bc, 0x29231b, 1.6); scene.add(hemi);
const moon = new THREE.DirectionalLight(0xffe6bd, 3.2); moon.position.set(-7, 12, 8); moon.castShadow = true;
moon.shadow.mapSize.set(2048,2048); moon.shadow.camera.left=-15; moon.shadow.camera.right=15; moon.shadow.camera.top=15; moon.shadow.camera.bottom=-15; moon.shadow.bias=-.0002; scene.add(moon);
const fill = new THREE.PointLight(0xd26935, 40, 18, 2); fill.position.set(0,3,-4); scene.add(fill);
const arena = new THREE.Group(); scene.add(arena);
const actors = new THREE.Group(); scene.add(actors);
let player, boss, playerWeapon, bossWeapon;
let gameState='menu', bossIndex=0, keys={}, pointer={x:0,y:0}, moveInput=new THREE.Vector2(), mobileMove=new THREE.Vector2();
let playerHP=100, stamina=100, bossHP=100, runes=0, playerLevel=1, attackCooldown=0, dodgeTime=0, invuln=0, bossAttackTimer=2.2, bossTelegraph=0, bossAttackKind='slam', bossStagger=0, abilityCooldown=0, playerAttack=0, playerAttackKind='light', hurtFlash=0, hitStop=0, particles=[], effects=[], shake=0, lastLog=0, soundOn=false, audio;

const roster = [
 ['THE HOLLOW WARDEN','Warden of the Cinder Gate','#8c342d','GREATSWORD',110,1.3],
 ['SISTER VESPER','The Bell-Toll Abbess','#b79a72','MACE',125,1.5],
 ['GARRON THE WOLF','Red-Handed Outlaw','#6d3029','DUAL',135,1.2],
 ['THE IRON PENITENT','Chain-Bound Confessor','#65706c','HAMMER',145,1.7],
 ['MORROW, ASH KNIGHT','Last Guard of Cinderfall','#914a31','GREATSWORD',155,1.4],
 ['THE MARSHAL OF THORNS','Thornwood Headsman','#627345','AXE',165,1.6],
 ['BLOODHOUND KRELL','Houndmaster of the Mire','#75433a','DUAL',175,1.15],
 ['THE PALE MATRIARCH','Mother of the Hollow','#c1b6a4','STAFF',185,1.45],
 ['DRAKE-EATER ORN','The Red Quarry','#9a5537','HAMMER',195,1.7],
 ['SABLE, KNIFE SAINT','A Blade in the Dark','#303b43','DUAL',205,1.1],
 ['THE FEN TITAN','Old God of Low Water','#657e65','HAMMER',215,1.8],
 ['CAPTAIN RUSK','Mutineer of the Salt Road','#9a7046','SPEAR',225,1.35],
 ['THE GRAVEN KNIGHT','Keeper of the Black Cairn','#4c505b','GREATSWORD',235,1.55],
 ['LADY CROWFIRE','Witch of the Burnt Choir','#883d38','STAFF',245,1.4],
 ['THE CROWNLESS KING','A King Without a Grave','#a28858','GREATSWORD',255,1.6],
 ['VARRIC, THE UNMADE','A Failed Saint','#655a75','SPEAR',270,1.3],
 ['THE SIEGE BEHEMOTH','Breaker of Nine Walls','#77776c','HAMMER',290,1.9],
 ['ORACLE OF THE DEEP','The Drowned Prophecy','#49717a','STAFF',305,1.35],
 ['THE LAST DRAGON','Ashwing, World-ender','#92463b','GREATSWORD',330,1.55],
 ['THE ASHEN SOVEREIGN','Lord of the Shattered March','#c39b58','GREATSWORD',380,1.25]
];
const mat=(color,roughness=.8,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
function mesh(geo,material,parent=arena,pos=[0,0,0],cast=true){const o=new THREE.Mesh(geo,material);o.position.set(...pos);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o;}
function box(parent,pos,scale,material,rot=0){const o=mesh(new THREE.BoxGeometry(...scale),material,parent,pos);o.rotation.y=rot;return o;}
function cylinder(parent,pos,r1,r2,h,material,segments=12){return mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material,parent,pos);}
function makeStoneFloor(){
 const floor=mesh(new THREE.CylinderGeometry(11,11,.42,64),mat('#383a34',.96),arena,[0,-.32,0]); floor.receiveShadow=true;
 const inner=mesh(new THREE.CylinderGeometry(8.7,8.7,.035,64),mat('#48473c',.97),arena,[0,-.09,0],false);
 for(let i=0;i<34;i++){const a=i/34*Math.PI*2,r=8.85;const tile=box(arena,[Math.cos(a)*r,-.048,Math.sin(a)*r],[1.08,.055,.42],mat(i%3?'#565247':'#625b49'),-a); tile.rotation.z=(Math.random()-.5)*.045;}
 const outer=mesh(new THREE.CylinderGeometry(11.25,11.25,.25,64,1,true),mat('#252a28'),arena,[0,-.22,0],false); outer.material.side=THREE.DoubleSide;
 for(let i=0;i<13;i++){const a=i/13*Math.PI*2,x=Math.cos(a)*10.15,z=Math.sin(a)*10.15; cylinder(arena,[x,.45,z],.42,.48,1.25,mat('#4b4c42'),8); cylinder(arena,[x,1.13,z],.53,.39,.2,mat('#686353'),8);}
 // fallen arches and a broken keep frame the arena.
 for(let side of [-1,1]){for(let i=0;i<4;i++){const x=side*(11.5+i*.68),h=2.6+Math.random()*1.5;box(arena,[x,h/2,-5],[.45,h,.5],mat('#343a36'),(Math.random()-.5)*.1);}box(arena,[side*13,4.4,-5],[3.3,.55,.7],mat('#383d37'),side*.11);}
 for(let i=0;i<18;i++){const a=Math.random()*Math.PI*2,r=12+Math.random()*7,h=1+Math.random()*4;const rock=cylinder(arena,[Math.cos(a)*r,h/2-1,Math.sin(a)*r],.7+Math.random(),.9+Math.random(),h,mat(i%2?'#242c29':'#303530'),5);rock.rotation.z=(Math.random()-.5)*.4;}
 // ember braziers
 for(const [x,z] of [[-7,-3],[7,-3],[-7,5],[7,5]]){cylinder(arena,[x,.48,z],.28,.45,.95,mat('#393a34'));cylinder(arena,[x,1.02,z],.48,.3,.2,mat('#68604d'));const flame=new THREE.PointLight(0xff6a30,24,7,2);flame.position.set(x,1.4,z);arena.add(flame);const f=mesh(new THREE.IcosahedronGeometry(.2,1),new THREE.MeshBasicMaterial({color:'#ff9b40'}),arena,[x,1.35,z],false);f.userData.flicker=Math.random()*10;effects.push(f);}
}
function makeHumanoid(isBoss,index=0){
 const group=new THREE.Group(), record=roster[index]||roster[0], size=isBoss?1.27:0.87;
 const armor=mat(isBoss?record[2]:'#59493a',.48,.38), dark=mat('#202321',.62,.22), cloth=mat(isBoss?'#40342d':'#3e332a',.9), skin=mat(isBoss?'#9c8872':'#b3967d'), steel=mat('#a3a18f',.28,.75), gold=mat('#b29356',.3,.72);
 group.scale.setScalar(size);
 const torso=mesh(new THREE.CapsuleGeometry(.43,.58,5,9),armor,group,[0,1.34,0]); torso.scale.set(.9,1,.65);
 const chest=mesh(new THREE.BoxGeometry(.74,.52,.56),armor,group,[0,1.55,-.015]);chest.rotation.z=-.035;
 const belt=mesh(new THREE.TorusGeometry(.35,.07,6,12),gold,group,[0,1.05,0]);belt.rotation.x=Math.PI/2;
 const head=mesh(new THREE.SphereGeometry(.3,12,10),skin,group,[0,2.1,0]);head.scale.set(.85,1.08,.82);
 const helm=mesh(new THREE.SphereGeometry(.33,10,8,0,Math.PI*2,0,Math.PI*.56),dark,group,[0,2.21,-.02]);helm.scale.set(1.05,.94,1);
 const visor=mesh(new THREE.BoxGeometry(.34,.075,.09),mat('#111719',.3,.5),group,[0,2.11,.26]);
 for(let s of [-1,1]){
  const shoulder=mesh(new THREE.SphereGeometry(.27,9,8),armor,group,[s*.53,1.72,0]);shoulder.scale.set(1,.82,.9);
  const upper=mesh(new THREE.CapsuleGeometry(.14,.43,4,7),armor,group,[s*.58,1.3,0]);upper.rotation.z=-s*.18;
  const lower=mesh(new THREE.CapsuleGeometry(.12,.38,4,7),dark,group,[s*.61,.88,.02]);lower.rotation.z=s*.1;
  const leg=mesh(new THREE.CapsuleGeometry(.16,.53,4,7),dark,group,[s*.23,.49,0]);leg.rotation.z=-s*.03;
  const boot=mesh(new THREE.BoxGeometry(.32,.17,.48),armor,group,[s*.23,.16,.09]);
  const knee=mesh(new THREE.SphereGeometry(.18,8,7),gold,group,[s*.23,.55,.13]);
 }
 const cape=mesh(new THREE.ConeGeometry(.52,1.18,7,1,true),cloth,group,[0,1.05,-.36]);cape.rotation.x=-Math.PI*.48;cape.scale.set(1,.92,.35);
 const weapon=new THREE.Group();group.add(weapon);weapon.position.set(.66,1.25,.16);
 const handle=mesh(new THREE.CylinderGeometry(.055,.065,.75,8),mat('#49352b'),weapon,[0,-.12,0]);
 const guard=mesh(new THREE.BoxGeometry(.5,.075,.13),gold,weapon,[0,.22,0]);guard.rotation.z=.08;
 const blade=mesh(new THREE.BoxGeometry(.16,1.15,.075),steel,weapon,[0,.82,0]);blade.rotation.z=-.025;
 const tip=mesh(new THREE.ConeGeometry(.115,.27,4),steel,weapon,[0,1.52,0]);
 const pommel=mesh(new THREE.SphereGeometry(.1,8,6),gold,weapon,[0,-.52,0]);
 if(record[3]==='HAMMER'||record[3]==='MACE'){blade.scale.set(1.55,.65,1.4);tip.scale.set(2,.6,1.8);}
 if(record[3]==='SPEAR'||record[3]==='STAFF'){handle.scale.y=1.65;blade.scale.y=.7;weapon.position.y=1.34;}
 group.userData={torso,head,weapon,cape,limbs:group.children.filter(c=>c.geometry?.type==='CapsuleGeometry'),phase:Math.random()*8,isBoss,index};
 return {group,weapon};
}
makeStoneFloor();
const ground=new THREE.Mesh(new THREE.PlaneGeometry(200,200),mat('#171c19',1));ground.rotation.x=-Math.PI/2;ground.position.y=-.57;ground.receiveShadow=true;scene.add(ground);
const moonDisc=mesh(new THREE.SphereGeometry(1.15,24,16),new THREE.MeshBasicMaterial({color:'#c7baa0'}),arena,[2,14,-28],false);moonDisc.material.transparent=true;moonDisc.material.opacity=.16;
const dustGeo=new THREE.BufferGeometry(), dustCount=500, dustPos=new Float32Array(dustCount*3);for(let i=0;i<dustCount;i++){dustPos[i*3]=(Math.random()-.5)*32;dustPos[i*3+1]=Math.random()*7;dustPos[i*3+2]=(Math.random()-.5)*32;}
dustGeo.setAttribute('position',new THREE.BufferAttribute(dustPos,3));const dust=new THREE.Points(dustGeo,new THREE.PointsMaterial({color:'#b8a981',size:.035,transparent:true,opacity:.58}));scene.add(dust);
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));}addEventListener('resize',resize);

const bandits=[];
function spawnBoss(){
 const data=roster[bossIndex];bossHP=data[4];bossAttackTimer=1.6;bossTelegraph=0;bossStagger=0;
 const made=makeHumanoid(true,bossIndex);boss=made.group;bossWeapon=made.weapon;boss.position.set((bossIndex%2?1:-1)*.6,0,-2.1);actors.add(boss);
 $('boss-title').textContent=data[0];$('boss-subtitle').textContent=data[1];$('boss-index').textContent=String(bossIndex+1).padStart(2,'0')+' / 20';$('boss-hp').style.width='100%';
 $('region-name').textContent=['CINDERFALL — OUTER KEEP','THORNWOOD — SUNKEN CHAPEL','THE BLACK CAIRN — GRAVEN ROAD','THE SALT WASTE — RED QUARRY','THE ASHEN THRONE — END OF ALL ROADS'][Math.min(4,Math.floor(bossIndex/4))];
}
function clearBandits(){for(const b of bandits)actors.remove(b.group);bandits.length=0;}
function spawnBandit(){if(bandits.length>=3||gameState!=='playing')return;const made=makeHumanoid(false,bossIndex);const a=Math.random()*Math.PI*2,r=6+Math.random()*1.8;made.group.position.set(Math.cos(a)*r,0,Math.sin(a)*r);actors.add(made.group);bandits.push({group:made.group,weapon:made.weapon,hp:28+bossIndex*1.5,attack:1+Math.random(),telegraph:0,stagger:0,phase:Math.random()*9});toast('BANDITS JOIN THE HUNT');}
function startGame(){
 $('intro').classList.add('is-leaving');$('hud').classList.remove('hidden');$('loading').style.opacity='0';setTimeout(()=>$('loading').style.display='none',550);
 playerHP=100;stamina=100;runes=0;playerLevel=1;bossIndex=0;gameState='playing';clearBandits();
 const made=makeHumanoid(false,0);player=made.group;playerWeapon=made.weapon;player.position.set(0,0,4);actors.add(player);spawnBoss();updateHud();log('THE GATE STIRS…');
}
function updateHud(){$('player-hp').style.width=Math.max(0,playerHP)+'%';$('player-stamina').style.width=Math.max(0,stamina)+'%';$('rune-count').textContent=String(runes).padStart(3,'0');$('level-label').textContent='LV. '+String(playerLevel).padStart(2,'0');$('boss-hp').style.width=Math.max(0,bossHP/roster[bossIndex][4]*100)+'%';}
function log(text){const el=$('combat-log');el.textContent=text;el.style.opacity='1';lastLog=2.2;}
function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1050);}
function sound(freq=130,duration=.09,type='triangle',volume=.035){if(!soundOn)return;try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function makeBurst(position,color='#e3ba69',count=12,power=3){for(let i=0;i<count;i++){const m=mesh(new THREE.IcosahedronGeometry(.035+Math.random()*.045,0),new THREE.MeshBasicMaterial({color,transparent:true}),actors,[position.x,position.y,position.z],false);const dir=new THREE.Vector3(Math.random()-.5,Math.random()*.9,Math.random()-.5).normalize();effects.push({object:m,velocity:dir.multiplyScalar(Math.random()*power+1),life:.42+Math.random()*.42,particle:true});}}
function doAttack(kind='light'){
 if(gameState!=='playing'||attackCooldown>0||stamina<(kind==='heavy'?27:8))return;
 const heavy=kind==='heavy';stamina-=heavy?27:8;attackCooldown=heavy?.58:.31;playerAttack=.25;playerAttackKind=kind;
 playerWeapon.rotation.set(-.22,0,heavy?-.88:.7);sound(heavy?83:170,heavy?.16:.09,heavy?'sawtooth':'triangle',.04);
 const dir=new THREE.Vector3(Math.sin(player.rotation.y),0,Math.cos(player.rotation.y));const reach=heavy?2.75:2.1;let hit=false;
 const targets=[{group:boss,kind:'boss'},...bandits.map(b=>({group:b.group,kind:'bandit',data:b}))];
 for(const t of targets){const delta=new THREE.Vector3(t.group.position.x-player.position.x,0,t.group.position.z-player.position.z);const d=delta.length();if(d<reach+(t.kind==='boss'?.65:0)&&d>.05&&dir.dot(delta.normalize())>.04){if(t.kind==='boss'){if(bossTelegraph>0)bossStagger=Math.max(bossStagger,.35);bossHP-=heavy?15:7.5;boss.position.addScaledVector(dir,.12);makeBurst(t.group.position.clone().add(new THREE.Vector3(0,1.3,0)),roster[bossIndex][2],heavy?20:9,heavy?4:2);if(bossHP<=0)defeatBoss();}
 else{t.data.hp-=heavy?22:12;t.data.stagger=.27;t.group.position.addScaledVector(dir,.35);makeBurst(t.group.position.clone().add(new THREE.Vector3(0,1,0)),'#d7ad70',9,2);if(t.data.hp<=0){actors.remove(t.group);bandits.splice(bandits.indexOf(t.data),1);runes+=14;toast('+14 RUNES');}}
 hit=true;}
 }
 if(hit){sound(heavy?68:95,.12,'square',.055);shake=heavy?.24:.12;}updateHud();
}
function dodge(){if(gameState!=='playing'||stamina<22||dodgeTime>0)return;stamina-=22;dodgeTime=.42;invuln=.48;const dir=new THREE.Vector3(moveInput.x,0,moveInput.y);if(dir.length()<.1)dir.set(Math.sin(player.rotation.y),0,Math.cos(player.rotation.y));dir.normalize();player.userData.dodgeDir=dir;makeBurst(player.position.clone().add(new THREE.Vector3(0,.45,0)),'#b8b8a0',10,1.7);sound(240,.12,'sine',.04);}
function ashBurst(){if(gameState!=='playing'||abilityCooldown>0||stamina<40)return;stamina-=40;abilityCooldown=5;shake=.2;const radius=4.4;makeBurst(player.position.clone().add(new THREE.Vector3(0,1,0)),'#e2bc73',34,5);sound(290,.4,'sawtooth',.045);
 if(boss.position.distanceTo(player.position)<radius){bossHP-=22;if(bossTelegraph>0)bossStagger=.75;boss.position.add(new THREE.Vector3(player.position.x-boss.position.x,0,player.position.z-boss.position.z).normalize().multiplyScalar(-.65));makeBurst(boss.position.clone().add(new THREE.Vector3(0,1.2,0)),'#e8c37b',16,3);if(bossHP<=0)defeatBoss();}
 for(let i=bandits.length-1;i>=0;i--){const b=bandits[i];if(b.group.position.distanceTo(player.position)<radius){b.hp-=36;b.stagger=.5;if(b.hp<=0){actors.remove(b.group);bandits.splice(i,1);runes+=14;}}}updateHud();toast('ASHEN BURST');}
function takeDamage(amount,source){if(invuln>0||gameState!=='playing')return;playerHP=Math.max(0,playerHP-amount);invuln=.52;hurtFlash=.22;shake=.28;makeBurst(player.position.clone().add(new THREE.Vector3(0,1,0)),'#b74436',10,2.2);sound(66,.2,'sawtooth',.05);log(source||'YOU ARE WOUNDED');updateHud();if(playerHP<=0)gameOver();}
function defeatBoss(){if(gameState!=='playing')return;bossHP=0;gameState='result';boss.userData.dead=true;boss.rotation.z=Math.PI/2;boss.position.y=.2;const reward=120+bossIndex*35;runes+=reward;updateHud();makeBurst(boss.position.clone().add(new THREE.Vector3(0,1,0)),'#e3bd75',60,7);sound(66,.55,'sawtooth',.05);$('result-eyebrow').textContent=bossIndex===19?'THE MARCH IS ENDED':'THE ROAD IS YOURS';$('result-title').textContent=bossIndex===19?'ASHEN SOVEREIGN':'VICTORY';$('result-copy').textContent=bossIndex===19?'The last crown falls. A new age begins in the ash.':'The gate falls silent. There are darker roads ahead.';$('result-reward').textContent='+'+reward+' RUNES';$('continue-btn').innerHTML=bossIndex===19?'CLAIM THE THRONE <span>✦</span>':'CONTINUE THE MARCH <span>↗</span>';if(bossIndex===19)$('continue-btn').textContent='CLAIM THE THRONE';$('result-overlay').classList.remove('hidden');log('WARLORD DEFEATED');}
function nextBoss(){if(bossIndex===19){$('result-overlay').classList.add('hidden');gameState='menu';$('hud').classList.add('hidden');$('intro').classList.remove('is-leaving');$('intro').querySelector('h1').innerHTML='THE MARCH<br><em>IS YOURS</em>';return;}bossIndex++;gameState='playing';actors.remove(boss);clearBandits();playerHP=Math.min(100,playerHP+38);stamina=100;playerLevel=1+Math.floor(bossIndex/3);player.position.set(0,0,4);player.rotation.set(0,0,0);spawnBoss();$('result-overlay').classList.add('hidden');toast('WANDERER RESTORED');log('BOSS '+String(bossIndex+1).padStart(2,'0')+' — '+roster[bossIndex][0]);updateHud();}
function gameOver(){gameState='dead';$('result-eyebrow').textContent='THE MARCH CLAIMS ANOTHER';$('result-title').textContent='YOU HAVE FALLEN';$('result-copy').textContent='The road is cruel, but your oath is not yet broken.';$('result-reward').textContent='RUNES HELD: '+runes;$('continue-btn').textContent='RISE AGAIN';$('result-overlay').classList.remove('hidden');}
function restart(){actors.clear();bandits.length=0;bossIndex=0;playerHP=100;stamina=100;runes=0;playerLevel=1;gameState='playing';const made=makeHumanoid(false,0);player=made.group;playerWeapon=made.weapon;player.position.set(0,0,4);actors.add(player);spawnBoss();$('result-overlay').classList.add('hidden');$('pause-overlay').classList.add('hidden');updateHud();}

