function updateBoss(dt){
 if(gameState!=='playing'||boss.userData.dead)return;
 const dx=player.position.x-boss.position.x,dz=player.position.z-boss.position.z,d=Math.hypot(dx,dz),speed=(1.15+bossIndex*.018);
 if(bossStagger>0){bossStagger-=dt;boss.userData.torso.rotation.x=.22;bossWeapon.rotation.z=.45;return;}boss.userData.torso.rotation.x=0;
 if(bossTelegraph>0){bossTelegraph-=dt;bossWeapon.rotation.z=-1.05;boss.userData.torso.rotation.x=-.19;if(bossTelegraph<=0){bossWeapon.rotation.z=0;bossAttackTimer=.95+Math.random()*.55;const currentD=boss.position.distanceTo(player.position);if(currentD<(bossAttackKind==='slam'?3.15:2.9)){if(invuln<=0)takeDamage(13+Math.floor(bossIndex*.42),'A WARLORD STRIKES');}else log('THE STRIKE MISSES');shake=.13;}return;}
 bossAttackTimer-=dt;
 if(d>2.65){boss.position.x+=(dx/Math.max(d,.001))*Math.min(speed*dt,d-2.45);boss.position.z+=(dz/Math.max(d,.001))*Math.min(speed*dt,d-2.45);}
 boss.rotation.y=Math.atan2(dx,dz);
 if(bossAttackTimer<=0){bossAttackKind=Math.random()>.35?'slam':'sweep';bossTelegraph=bossAttackKind==='slam'?.78:.6;bossAttackTimer=2;log(bossAttackKind==='slam'?'THE WARLORD GATHERS STRENGTH':'A BLADE INCOMING');}
}
function updateBandits(dt){for(const b of [...bandits]){if(b.stagger>0){b.stagger-=dt;continue;}const dx=player.position.x-b.group.position.x,dz=player.position.z-b.group.position.z,d=Math.hypot(dx,dz);b.group.rotation.y=Math.atan2(dx,dz);b.attack-=dt;
 if(b.telegraph>0){b.telegraph-=dt;if(b.telegraph<=0){if(d<2.1)takeDamage(6+bossIndex*.16,'A BANDIT CUTS DEEP');b.attack=1.35+Math.random();}continue;}
 if(d>1.55){b.group.position.x+=dx/Math.max(d,.001)*Math.min(1.75*dt,d-1.42);b.group.position.z+=dz/Math.max(d,.001)*Math.min(1.75*dt,d-1.42);}else if(b.attack<=0){b.telegraph=.38;b.weapon.rotation.z=-.8;}
 }}
function update(dt){
 const time=clock.elapsedTime;attackCooldown=Math.max(0,attackCooldown-dt);abilityCooldown=Math.max(0,abilityCooldown-dt);invuln=Math.max(0,invuln-dt);hurtFlash=Math.max(0,hurtFlash-dt);hitStop=Math.max(0,hitStop-dt);lastLog=Math.max(0,lastLog-dt);if(lastLog===0)$('combat-log').style.opacity='0';
 if(gameState==='playing'&&hitStop===0){
  stamina=Math.min(100,stamina+(keys.Shift?9:17)*dt);
  moveInput.set((keys.KeyD?1:0)-(keys.KeyA?1:0),(keys.KeyS?1:0)-(keys.KeyW?1:0));if(moveInput.length()>1)moveInput.normalize();if(mobileMove.length()>0)moveInput.copy(mobileMove);
  if(dodgeTime>0){dodgeTime-=dt;player.position.addScaledVector(player.userData.dodgeDir,8.5*dt);}
  else if(moveInput.length()>.02){const speed=keys.Shift&&stamina>0?5.8:4.15;if(keys.Shift)stamina=Math.max(0,stamina-22*dt);player.position.x+=moveInput.x*speed*dt;player.position.z+=moveInput.y*speed*dt;const desired=Math.atan2(moveInput.x,moveInput.y);player.rotation.y=THREE.MathUtils.damp(player.rotation.y,desired,12,dt);}
  player.position.x=THREE.MathUtils.clamp(player.position.x,-8.8,8.8);player.position.z=THREE.MathUtils.clamp(player.position.z,-8.8,8.8);
  const moving=moveInput.length()>.03;player.userData.phase+=dt*(moving?11:3);player.userData.limbs.forEach((limb,i)=>{if(limb.geometry.type==='CapsuleGeometry'){const leg=limb.position.y<.7;limb.rotation.x=leg&&moving?Math.sin(player.userData.phase+i*2.7)*.55:0;}});
  if(playerAttack>0){playerAttack-=dt;const p=1-playerAttack/.25;playerWeapon.rotation.z=playerAttackKind==='heavy'?(-.9+Math.sin(p*Math.PI)*1.6):(.72-Math.sin(p*Math.PI)*1.1);if(playerAttack<=0)playerWeapon.rotation.z=0;}
  if(invuln>0)player.visible=Math.floor(time*18)%2===0;else player.visible=true;
  updateBoss(dt);updateBandits(dt);
  if(bossHP<roster[bossIndex][4]*.54&&bandits.length===0&&Math.random()<dt*.018)spawnBandit();
  if(bossTelegraph>0){boss.userData.weapon.material?.color?.set?.('#c66b36');}else if(boss.userData.weapon){boss.userData.weapon.rotation.z=0;}
 }
 // camera tracks the duel; player remains in the lower third of frame.
 if(player){const focusX=player.position.x*.48+(boss?.position.x||0)*.20,focusZ=player.position.z*.42-2.05;const target=new THREE.Vector3(focusX,0,focusZ);camera.position.lerp(new THREE.Vector3(focusX,11.3,focusZ+14.2),1-Math.exp(-dt*2.8));camera.lookAt(target);}
 fill.intensity=34+Math.sin(time*7)*4;for(const e of effects){if(e.userData?.flicker!==undefined){e.scale.setScalar(.85+Math.sin(time*11+e.userData.flicker)*.24);e.position.y=1.36+Math.sin(time*7+e.userData.flicker)*.07;}}
 for(let i=effects.length-1;i>=0;i--){const e=effects[i];if(!e.particle)continue;e.life-=dt;e.object.position.addScaledVector(e.velocity,dt);e.velocity.y-=5*dt;e.object.material.opacity=Math.max(0,e.life);e.object.scale.multiplyScalar(.985);if(e.life<=0){actors.remove(e.object);effects.splice(i,1);}}
 const pos=dust.geometry.attributes.position;for(let i=1;i<dustCount;i++){let y=pos.array[i*3+1]+dt*.08;if(y>7)y=0;pos.array[i*3+1]=y;}pos.needsUpdate=true;
 if(shake>0){shake=Math.max(0,shake-dt);camera.position.x+=(Math.random()-.5)*shake*.18;camera.position.y+=(Math.random()-.5)*shake*.14;}
 updateHud();
}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);update(dt);renderer.render(scene,camera);}animate();

$('start-btn').addEventListener('click',()=>startGame());
$('pause-btn').addEventListener('click',()=>{if(gameState==='playing'){gameState='paused';$('pause-overlay').classList.remove('hidden');}});
$('resume-btn').addEventListener('click',()=>{gameState='playing';$('pause-overlay').classList.add('hidden');});
$('restart-btn').addEventListener('click',()=>{restart();$('intro').classList.add('is-leaving');$('hud').classList.remove('hidden');});
$('continue-btn').addEventListener('click',()=>{if(gameState==='dead'){restart();return;}nextBoss();});
$('retry-btn').addEventListener('click',()=>restart());
$('sound-btn').addEventListener('click',()=>{soundOn=!soundOn;$('sound-btn').style.color=soundOn?'#f0d496':'';if(soundOn){audio??=new AudioContext();sound(440,.1,'sine');}});
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Space')dodge();if(e.code==='KeyQ')doAttack('heavy');if(e.code==='KeyE')ashBurst();if(e.code==='Escape'&&gameState==='playing'){$('pause-btn').click();}if(e.code==='Enter'&&gameState==='menu')startGame();});
addEventListener('keyup',e=>keys[e.code]=false);
canvas.addEventListener('pointerdown',e=>{if(e.button===0)doAttack('light');else if(e.button===2)doAttack('heavy');});canvas.addEventListener('contextmenu',e=>e.preventDefault());
for(const button of document.querySelectorAll('.mobile-actions button')){const act=button.dataset.action;button.addEventListener('pointerdown',e=>{e.preventDefault();if(act==='attack')doAttack('light');if(act==='heavy')doAttack('heavy');if(act==='dodge')dodge();if(act==='ability')ashBurst();});}
const stickZone=$('stick-zone'),stick=$('stick');let stickPointer=null;
stickZone.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stickZone.setPointerCapture(e.pointerId);moveStick(e);});
stickZone.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)moveStick(e);});
function moveStick(e){const r=stickZone.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=43,len=Math.min(max,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);stick.style.transform=`translate(${Math.cos(a)*len}px,${Math.sin(a)*len}px)`;mobileMove.set(Math.cos(a)*len/max,Math.sin(a)*len/max);}
function resetStick(e){if(e.pointerId===stickPointer){stickPointer=null;mobileMove.set(0,0);stick.style.transform='';}}
stickZone.addEventListener('pointerup',resetStick);stickZone.addEventListener('pointercancel',resetStick);

// The first scene is rendered before the title fades in, avoiding a blank-screen impression.
setTimeout(()=>{$('loading').style.opacity='0';setTimeout(()=>$('loading').style.display='none',550);},500);

