const bandits=[];
function makeHumanoid(isBoss,index=0){
 const group=new THREE.Group(), record=roster[index]||roster[0], size=isBoss?1.27:.87;
 const armor=mat(isBoss?record[2]:'#59493a',.48,.38), dark=mat('#202321',.62,.22), cloth=mat('#40342d',.9), skin=mat('#9c8872'), steel=mat('#a3a18f',.28,.75), gold=mat('#b29356',.3,.72);
 group.scale.setScalar(size);
 const torso=mesh(new THREE.CapsuleGeometry(.43,.58,5,9),armor,group,[0,1.34,0]); torso.scale.set(.9,1,.65);
 mesh(new THREE.BoxGeometry(.74,.52,.56),armor,group,[0,1.55,-.015]);
 const belt=mesh(new THREE.TorusGeometry(.35,.07,6,12),gold,group,[0,1.05,0]); belt.rotation.x=Math.PI/2;
 const head=mesh(new THREE.SphereGeometry(.3,12,10),skin,group,[0,2.1,0]); head.scale.set(.85,1.08,.82);
 const helm=mesh(new THREE.SphereGeometry(.33,10,8,0,Math.PI*2,0,Math.PI*.56),dark,group,[0,2.21,-.02]); helm.scale.set(1.05,.94,1);
 mesh(new THREE.BoxGeometry(.34,.075,.09),mat('#111719',.3,.5),group,[0,2.11,.26]);
 const limbs=[];
 for(const s of [-1,1]){
  const shoulder=mesh(new THREE.SphereGeometry(.27,9,8),armor,group,[s*.53,1.72,0]); shoulder.scale.set(1,.82,.9);
  const upper=mesh(new THREE.CapsuleGeometry(.14,.43,4,7),armor,group,[s*.58,1.3,0]); upper.rotation.z=-s*.18; limbs.push(upper);
  const lower=mesh(new THREE.CapsuleGeometry(.12,.38,4,7),dark,group,[s*.61,.88,.02]); lower.rotation.z=s*.1; limbs.push(lower);
  const leg=mesh(new THREE.CapsuleGeometry(.16,.53,4,7),dark,group,[s*.23,.49,0]); limbs.push(leg);
  mesh(new THREE.BoxGeometry(.32,.17,.48),armor,group,[s*.23,.16,.09]);
  mesh(new THREE.SphereGeometry(.18,8,7),gold,group,[s*.23,.55,.13]);
 }
 const cape=mesh(new THREE.ConeGeometry(.52,1.18,7,1,true),cloth,group,[0,1.05,-.36]); cape.rotation.x=-Math.PI*.48; cape.scale.set(1,.92,.35);
 const weapon=new THREE.Group(); group.add(weapon); weapon.position.set(.66,1.25,.16);
 mesh(new THREE.CylinderGeometry(.055,.065,.75,8),mat('#49352b'),weapon,[0,-.12,0]);
 const guard=mesh(new THREE.BoxGeometry(.5,.075,.13),gold,weapon,[0,.22,0]); guard.rotation.z=.08;
 const blade=mesh(new THREE.BoxGeometry(.16,1.15,.075),steel,weapon,[0,.82,0]); blade.rotation.z=-.025;
 mesh(new THREE.ConeGeometry(.115,.27,4),steel,weapon,[0,1.52,0]); mesh(new THREE.SphereGeometry(.1,8,6),gold,weapon,[0,-.52,0]);
 if(['HAMMER','MACE'].includes(record[3])) blade.scale.set(1.55,.65,1.4);
 if(['SPEAR','STAFF'].includes(record[3])){weapon.children[0].scale.y=1.65; blade.scale.y=.7; weapon.position.y=1.34;}
 group.userData={torso,head,weapon,cape,limbs,phase:Math.random()*8,isBoss,index};
 return{group,weapon};
}
function spawnBoss(){const data=roster[bossIndex];bossHP=data[4];bossAttackTimer=1.6;bossTelegraph=0;bossStagger=0;const made=makeHumanoid(true,bossIndex);boss=made.group;bossWeapon=made.weapon;boss.position.set((bossIndex%2?1:-1)*.6,0,-2.1);actors.add(boss);$('boss-title').textContent=data[0];$('boss-subtitle').textContent=data[1];$('boss-index').textContent=String(bossIndex+1).padStart(2,'0')+' / 20';$('boss-hp').style.width='100%';$('region-name').textContent=['CINDERFALL — OUTER KEEP','THORNWOOD — SUNKEN CHAPEL','THE BLACK CAIRN — GRAVEN ROAD','THE SALT WASTE — RED QUARRY','THE ASHEN THRONE — END OF ALL ROADS'][Math.min(4,Math.floor(bossIndex/4))];}
function clearBandits(){for(const b of bandits)actors.remove(b.group);bandits.length=0;}
function spawnBandit(){if(bandits.length>=3||gameState!=='playing')return;const made=makeHumanoid(false,bossIndex),a=Math.random()*Math.PI*2,r=6+Math.random()*1.8;made.group.position.set(Math.cos(a)*r,0,Math.sin(a)*r);actors.add(made.group);bandits.push({group:made.group,weapon:made.weapon,hp:28+bossIndex*1.5,attack:1+Math.random(),telegraph:0,stagger:0});toast('BANDITS JOIN THE HUNT');}
function updateHud(){$('player-hp').style.width=Math.max(0,playerHP)+'%';$('player-stamina').style.width=Math.max(0,stamina)+'%';$('rune-count').textContent=String(runes).padStart(3,'0');$('level-label').textContent='LV. '+String(playerLevel).padStart(2,'0');if(roster[bossIndex])$('boss-hp').style.width=Math.max(0,bossHP/roster[bossIndex][4]*100)+'%';}
function log(text){const el=$('combat-log');el.textContent=text;el.style.opacity='1';lastLog=2.2;}
function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1050);}
function sound(freq=130,duration=.09,type='triangle',volume=.035){if(!soundOn)return;try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
function makeBurst(position,color='#e3ba69',count=12,power=3){for(let i=0;i<count;i++){const m=mesh(new THREE.IcosahedronGeometry(.035+Math.random()*.045,0),new THREE.MeshBasicMaterial({color,transparent:true}),actors,[position.x,position.y,position.z],false),dir=new THREE.Vector3(Math.random()-.5,Math.random()*.9,Math.random()-.5).normalize();effects.push({object:m,velocity:dir.multiplyScalar(Math.random()*power+1),life:.42+Math.random()*.42,particle:true});}}
function doAttack(kind='light'){if(gameState!=='playing'||attackCooldown>0||stamina<(kind==='heavy'?27:8))return;const heavy=kind==='heavy';stamina-=heavy?27:8;attackCooldown=heavy?.58:.31;playerAttack=.25;playerAttackKind=kind;playerWeapon.rotation.set(-.22,0,heavy?-.88:.7);sound(heavy?83:170,heavy?.16:.09,heavy?'sawtooth':'triangle',.04);const targets=[boss,...bandits.map(b=>b.group)];let nearest=null,nearestD=Infinity;for(const target of targets){const d=target.position.distanceTo(player.position);if(d<nearestD){nearest=target;nearestD=d;}}if(nearest){const dx=nearest.position.x-player.position.x,dz=nearest.position.z-player.position.z;player.rotation.y=Math.atan2(dx,dz);}const dir=new THREE.Vector3(Math.sin(player.rotation.y),0,Math.cos(player.rotation.y)),reach=heavy?2.75:2.1;let hit=false;for(const t of targets){const delta=new THREE.Vector3(t.position.x-player.position.x,0,t.position.z-player.position.z),d=delta.length();if(d<reach+(t===boss?.65:0)&&d>.05&&dir.dot(delta.normalize())>.04){if(t===boss){if(bossTelegraph>0)bossStagger=Math.max(bossStagger,.35);bossHP-=heavy?15:7.5;boss.position.addScaledVector(dir,.12);makeBurst(boss.position.clone().add(new THREE.Vector3(0,1.3,0)),roster[bossIndex][2],heavy?20:9,heavy?4:2);if(bossHP<=0)defeatBoss();}else{const b=bandits.find(v=>v.group===t);if(!b)continue;b.hp-=heavy?22:12;b.stagger=.27;b.group.position.addScaledVector(dir,.35);makeBurst(t.position.clone().add(new THREE.Vector3(0,1,0)),'#d7ad70',9,2);if(b.hp<=0){actors.remove(b.group);bandits.splice(bandits.indexOf(b),1);runes+=14;toast('+14 RUNES');}}hit=true;}}if(hit){sound(heavy?68:95,.12,'square',.055);shake=heavy?.24:.12;}updateHud();}
function dodge(){if(gameState!=='playing'||stamina<22||dodgeTime>0)return;stamina-=22;dodgeTime=.42;invuln=.48;const dir=new THREE.Vector3(moveInput.x,0,moveInput.y);if(dir.length()<.1)dir.set(Math.sin(player.rotation.y),0,Math.cos(player.rotation.y));dir.normalize();player.userData.dodgeDir=dir;makeBurst(player.position.clone().add(new THREE.Vector3(0,.45,0)),'#b8b8a0',10,1.7);sound(240,.12,'sine',.04);}
function ashBurst(){if(gameState!=='playing'||abilityCooldown>0||stamina<40)return;stamina-=40;abilityCooldown=5;shake=.2;const radius=4.4;makeBurst(player.position.clone().add(new THREE.Vector3(0,1,0)),'#e2bc73',34,5);sound(290,.4,'sawtooth',.045);if(boss.position.distanceTo(player.position)<radius){bossHP-=22;if(bossTelegraph>0)bossStagger=.75;boss.position.add(new THREE.Vector3(player.position.x-boss.position.x,0,player.position.z-boss.position.z).normalize().multiplyScalar(-.65));makeBurst(boss.position.clone().add(new THREE.Vector3(0,1.2,0)),'#e8c37b',16,3);if(bossHP<=0)defeatBoss();}for(let i=bandits.length-1;i>=0;i--){const b=bandits[i];if(b.group.position.distanceTo(player.position)<radius){b.hp-=36;b.stagger=.5;if(b.hp<=0){actors.remove(b.group);bandits.splice(i,1);runes+=14;}}}updateHud();toast('ASHEN BURST');}
function takeDamage(amount,source){if(invuln>0||gameState!=='playing')return;playerHP=Math.max(0,playerHP-amount);invuln=.52;hurtFlash=.22;shake=.28;makeBurst(player.position.clone().add(new THREE.Vector3(0,1,0)),'#b74436',10,2.2);sound(66,.2,'sawtooth',.05);log(source||'YOU ARE WOUNDED');updateHud();if(playerHP<=0)gameOver();}
function startGame(){if(!player){const p=makeHumanoid(false,0);player=p.group;playerWeapon=p.weapon;actors.add(player);}else actors.add(player);player.position.set(0,0,4);playerHP=100;stamina=100;runes=0;playerLevel=1;bossIndex=0;gameState='playing';clearBandits();if(boss)actors.remove(boss);spawnBoss();$('intro').classList.add('is-leaving');$('hud').classList.remove('hidden');$('loading').style.display='none';updateHud();log('THE GATE STIRS…');}
function defeatBoss(){if(gameState!=='playing')return;bossHP=0;gameState='result';boss.rotation.z=Math.PI/2;boss.position.y=.2;const reward=120+bossIndex*35;runes+=reward;updateHud();makeBurst(boss.position.clone().add(new THREE.Vector3(0,1,0)),'#e3bd75',60,7);sound(66,.55,'sawtooth',.05);$('result-eyebrow').textContent=bossIndex===19?'THE MARCH IS ENDED':'THE ROAD IS YOURS';$('result-title').textContent=bossIndex===19?'ASHEN SOVEREIGN':'VICTORY';$('result-copy').textContent=bossIndex===19?'The last crown falls. A new age begins in the ash.':'The gate falls silent. There are darker roads ahead.';$('result-reward').textContent='+'+reward+' RUNES';$('continue-btn').textContent=bossIndex===19?'CLAIM THE THRONE':'CONTINUE THE MARCH';$('result-overlay').classList.remove('hidden');log('WARLORD DEFEATED');}
